int n;
vector<bool> cols, diag, anti;        // diag idx: r-c+n, anti idx: r+c

int solve(int row) {
    if (row == n) return 1;
    int count = 0;
    for (int c = 0; c < n; ++c) {
        if (cols[c] || diag[row - c + n] || anti[row + c]) continue;
        cols[c] = diag[row - c + n] = anti[row + c] = true;
        count += solve(row + 1);
        cols[c] = diag[row - c + n] = anti[row + c] = false;   // backtrack
    }
    return count;
}

def total_n_queens(n):
    cols, diag, anti = set(), set(), set()
    def solve(row):
        if row == n: return 1
        count = 0
        for c in range(n):
            if c in cols or (row-c) in diag or (row+c) in anti:
                continue
            cols.add(c); diag.add(row-c); anti.add(row+c)
            count += solve(row + 1)
            cols.remove(c); diag.remove(row-c); anti.remove(row+c)
        return count
    return solve(0)
